sys_ws_operation.operation_script:
(function process(request, response) {
    try {
        var input = request.body.data;

        if (!input) {
            response.setStatus(400);
            response.setBody({
                error: 'Missing request body'
            });
            return;
        }

        var service = new ProjectMCPStoryService();
        var result = service.createStory(input);

        if (!result.success) {
            response.setStatus(result.status || 400);

            gs.error(
                'project.story.create service error: ' +
                result.error
            );

            response.setBody({
                error: 'Request failed. See server logs for details.'
            });

            return;
        }

        response.setStatus(201);
        response.setBody(result.data);

    } catch (e) {
        gs.error(
            'project.story.create error: ' +
            e.message
        );

        response.setStatus(500);
        response.setBody({
            error: 'Internal error processing request'
        });
    }
})(request, response);
